    final ListIterator<String> iterator = tokenList.listIterator();
    // process each flattened token while (iterator.hasNext())
    {
        final String token = iterator.next();
        if (token != null)
        {
            // the value is the double-dash if ("--".equals(token))
            {
                eatTheRest = true;
            }
            else if ("-".equals(token))
            {
                // the value is a single dash if (stopAtNonOption)
                {
                    eatTheRest = true;
                }
                else
                {
                    cmd.addArg(token);
                }
            }
            else if (token.startsWith("-"))
            {
                // the value is an option if (stopAtNonOption && !getOptions().hasOption(token))
                {
                    eatTheRest = true;
                    cmd.addArg(token);
                }
                else
                {
                    processOption(token, iterator);
