    "code": "```java
private static String encode(final Map<String, String> args, final boolean concat, final String input)  {
    final Languages.LanguageSet languageSet;
    final PhoneticEngine engine;
    // PhoneticEngine = NameType + RuleType + concat // we use common-codec's defaults: GENERIC + APPROX + true final String nameTypeArg = args.get("nameType");
    final NameType nameType = nameTypeArg == null ? NameType.GENERIC : NameType.valueOf(nameTypeArg);
    final String ruleTypeArg = args.get("ruleType");
    final RuleType ruleType = ruleTypeArg == null ? RuleType.APPROX : RuleType.valueOf(ruleTypeArg);
    engine = new PhoneticEngine(nameType, ruleType, concat);
    // LanguageSet: defaults to automagic, otherwise a comma-separated list. final String languageSetArg = args.get("languageSet");
    if (languageSetArg == null || languageSetArg.equals("auto"))
    {
        languageSet = null;
    }
    else
    {
        languageSet = Languages.LanguageSet.from(new HashSet<>(Arrays.asList(COMMA_PATTERN.split(languageSetArg))));
    }
    /* org/apache/lucene/analysis/phonetic/BeiderMorseFilter.java (lines 96-98) does this: encoded = (languages == null) ? engine.encode(termAtt.toString()) : engine.encode(termAtt.toString(), languages);
    Hence our approach, below: */ if (languageSet == null)
    {
        return engine.encode(input);
    }
    return engine.encode(input, languageSet);
}
