public long skip(final long n) throws IOException  {
    long remaining = n;
    int nr;
    if (n <= 0)
    {
        return 0;
    }
    final int size = (int) Math.min(SKIP_BUFFER_SIZE, remaining);
    final ByteBuffer skipBuffer = getSkipBuf();
    while (remaining > 0)
    {
        skipBuffer.clear();
        skipBuffer.limit((int) Math.min(size, remaining));
        nr = read(skipBuffer);
        if (nr < 0)
