    "code": "```java\nprotected void doExceptionTest(final String cipherClass, final ByteArrayOutputStream baos, final boolean withChannel) throws IOException  {\n    assumeJniPresence(cipherClass);\n    // Test InvalidAlgorithmParameters Exception ex = assertThrows(IOException.class, () -> newCryptoInputStream(transformation, props, new ByteArrayInputStream(encData), AES.newSecretKeySpec(key), new GCMParameterSpec(0, new byte[0]), withChannel));\n    assertEquals(ex.getMessage(), \"Illegal parameters\");\n    // Test InvalidAlgorithmParameters ex = assertThrows(IOException.class, () -> newCryptoOutputStream(transformation, props, baos, AES.newSecretKeySpec(key), new GCMParameterSpec(0, new byte[0]), withChannel));\n    assertEquals(ex.getMessage(), \"Illegal parameters\");\n    // Test Invalid Key assertThrows(IOException.class, () -> newCryptoInputStream(transformation, props, new ByteArrayInputStream(encData), AES.newSecretKeySpec(new byte[10]), new IvParameterSpec(iv), withChannel));\n    // Test Invalid Key assertThrows(IOException.class, () -> newCryptoOutputStream(transformation, props, baos, new byte[10], new IvParameterSpec(iv), withChannel));\n    // Test reading a closed stream. InputStream closedIn;\n    try (CryptoCipher cipher = getCipher(cipherClass);\n    final InputStream in = newCryptoInputStream(new ByteArrayInputStream(encData), cipher, defaultBufferSize, iv, withChannel))\n    {\n        closedIn = in;\n    }\n    // Throw exception. ex = assertThrows(IOException.class, closedIn::read);\n    assertEquals(ex.getMessage(), \"Stream closed\");\n    // Test closing a closed stream. try\n    {\n        closedIn.close();\n        // Don't throw exception on double-close.\n    }\n    catch (final IOException ioEx)\n    {\n        fail(\"Should not throw exception closing a closed stream.\");\n    }\n    // Test checking a closed stream. final OutputStream out = newCryptoOutputStream(transformation, props, baos, key, new IvParameterSpec(iv), withChannel);\n    out.close();\n    // Throw exception. assertThrows(IOException.class, ((CryptoOutputStream) out)::checkStream);\n    // Test closing a closed stream. try\n    {\n        out.close();\n        // Don't throw exception.\n    }\n    catch (final IOException ioEx)\n    {\n        fail(\"Should not throw exception closing a closed stream.\");\n    }\n    // Test checkStreamCipher try (CryptoCipher cipher = getCipher(cipherClass))\n    {\n        CryptoInputStream.checkStreamCipher(cipher);\n    }\n    catch (final IOException ioEx)\n    {\n        assertEquals(ioEx.getMessage(), \"AES/CTR/NoPadding is required\");\n    }\n    finally\n    {\n        closedIn.close();\n    }\n    // Test unsupported operation handling. try (CryptoCipher cipher = getCipher(cipherClass);\n    final InputStream inNewCrytptoStr = newCryptoInputStream(new ByteArrayInputStream(encData), cipher, defaultBufferSize, iv, false))\n    {\n        closedIn.mark(0);\n        assertFalse(closedIn.markSupported());\n        ex = assertThrows(IOException.class, inNewCrytptoStr::reset);\n        assertEquals(ex.getMessage(), \"mark/reset not supported\");\n    }\n}\n```"
