protected void beginRead(final boolean optimize)  {
    if (optimize)
    {
        // just need a lock, don't construct configuration super.beginRead(true);
        return;
    }
    boolean lockObtained = false;
    do
    {
        super.beginRead(false);
        if (isUpToDate())
        {
